seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
rc=lambda s: s.translate(str.maketrans('ACGT','TGCA'))[::-1]
STOPS=('TAA','TAG','TGA'); STARTS=('ATG','GTG','TTG')

def orf_list(t,minaa=50):
    out=[]
    for f in range(3):
        starts=[]
        for j in range(f,len(t)-2,3):
            c=t[j:j+3]
            if c in STARTS: starts.append(j)
            if c in STOPS:
                for s in starts:
                    if j-s>=minaa*3: out.append((s,j+3,j+3-s))
                starts=[]
        for s in starts:
            if len(t)-s>=minaa*3: out.append((s,len(t),len(t)-s))
    return out

